/** 
 * Returns an InetAddress representing the literal IPv4 or IPv6 host portion of a URL, encoded in the format specified by RFC 3986 section 3.2.2. <p>This function is similar to  {@link InetAddresses#forString(String)}, however, it requires that IPv6 addresses are surrounded by square brackets. <p>This function is the inverse of {@link InetAddresses#toUriString(java.net.InetAddress)}.
 * @param hostAddr A RFC 3986 section 3.2.2 encoded IPv4 or IPv6 address
 * @return an InetAddress representing the address in {@code hostAddr}
 * @throws IllegalArgumentException if {@code hostAddr} is not a validIPv4 address, or IPv6 address surrounded by square brackets
 */
public static InetAddress forUriString(String hostAddr){
  Preconditions.checkNotNull(hostAddr);
  Preconditions.checkArgument(hostAddr.length() > 0,"host string is empty");
  InetAddress retval=null;
  try {
    retval=forString(hostAddr);
    if (retval instanceof Inet4Address) {
      return retval;
    }
  }
 catch (  IllegalArgumentException e) {
    throw new IllegalArgumentException("Invalid IPv4 address: " + hostAddr, e);
  }
  if (!(hostAddr.startsWith("[") && hostAddr.endsWith("]"))) {
    throw new IllegalArgumentException("Not a valid address: \"" + hostAddr + "\"");
  }
  retval=forString(hostAddr.substring(1,hostAddr.length() - 1));
  if (retval instanceof Inet6Address) {
    return retval;
  }
  throw new IllegalArgumentException("Not a valid address: \"" + hostAddr + "\"");
}
